async function busy(button,fn){const label=button.textContent,wasDisabled=button.disabled;button.disabled=true;button.textContent='처리 중…';try{return await fn();}finally{button.textContent=label;button.disabled=wasDisabled;if(button.id==='apply-model')syncApplyState();}}
function safeTime(value){const parts=formatTimeParts(value);return parts.absolute||parts.relative;}

function routeFromLocation(){const parts=location.hash.replace(/^#/,'').split('/');return {view:['tasks','records','settings'].includes(parts[0])?parts[0]:'tasks',settings:['ai','files','external','privacy'].includes(parts[1])?parts[1]:'ai'};}
function navigate(view,settings,{replace=false}={}){activeView=view;activeSettings=settings||activeSettings;const hash='#'+view+(view==='settings'?'/'+activeSettings:'');if(location.hash!==hash)history[replace?'replaceState':'pushState'](null,'',hash);renderNavigation();}
function renderNavigation(){document.querySelectorAll('[data-view-panel]').forEach(panel=>panel.hidden=panel.dataset.viewPanel!==activeView);document.querySelectorAll('[data-view]').forEach(button=>{const current=button.dataset.view===activeView;button.classList.toggle('active',current);if(current)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});document.querySelectorAll('[data-settings-panel]').forEach(panel=>panel.hidden=panel.dataset.settingsPanel!==activeSettings);document.querySelectorAll('[data-settings]').forEach(button=>{const selected=button.dataset.settings===activeSettings;button.classList.toggle('active',selected);button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;});}
function showRecords(){if(recordPageMatches(lastRecords,$('record-query').value,$('record-filter').value)){recordRenderFingerprint='';renderRecords();void refreshLoadedRecords();}else void loadRecords();}
document.querySelectorAll('[data-view]').forEach(button=>button.onclick=()=>{navigate(button.dataset.view);if(button.dataset.view==='records')showRecords();});
document.querySelectorAll('[data-settings]').forEach(button=>{button.onclick=()=>navigate('settings',button.dataset.settings);button.onkeydown=event=>{if(!['ArrowDown','ArrowUp','ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=[...document.querySelectorAll('[data-settings]')],index=tabs.indexOf(button),forward=event.key==='ArrowDown'||event.key==='ArrowRight',next=event.key==='Home'?tabs[0]:event.key==='End'?tabs[tabs.length-1]:tabs[(index+(forward?1:-1)+tabs.length)%tabs.length];navigate('settings',next.dataset.settings);next.focus();};});
$('brand-home').onclick=event=>{event.preventDefault();navigate('tasks');};
window.addEventListener('popstate',()=>{const route=routeFromLocation();activeView=route.view;activeSettings=route.settings;renderNavigation();if(activeView==='records')showRecords();});

function modelDraft(){const endpoint=normalizeEndpoint($('endpoint').value);if(!activeModelDestination)activeModelDestination=[$('provider').value,endpoint].join('|');return {provider:$('provider').value,endpoint,model:$('model-name').value.trim(),api_key:$('api-key').value,require_key:activeModelDestination!==[$('provider').value,endpoint].join('|'),credential_revision:modelGuard.revision()};}
function syncApplyState(){const ready=modelGuard.canApply(modelDraft()),button=$('apply-model');button.disabled=!ready;button.textContent=ready?'이 설정 적용':'테스트 후 적용';}
function invalidateModelDraft(message){modelGuard.invalidate();syncApplyState();if(message)setFeedback('model-feedback',message);}
function invalidateModelLoad(){modelLoadRevision++;modelLoaded=false;}
function invalidateRootsLoad(){rootsLoadRevision++;}
function invalidateFileWorkspaceLoad(){fileWorkspaceLoadRevision++;}
function applyModelPreset(preset,message){const draft=modelPresetDraft(preset);$('provider').value=draft.provider;$('endpoint').value=draft.endpoint;$('model-name').value=draft.model;$('api-key').value=draft.api_key;invalidateModelDraft(message);focusSettingsTarget('advanced-model','test-model');}
$('provider').onchange=()=>{const selected=providers[$('provider').value];$('endpoint').value=selected.endpoint;if(selected.model)$('model-name').value=selected.model;$('api-key').value='';$('endpoint-help').textContent=selected.help;invalidateModelDraft('연결 대상이 바뀌었습니다. 새 설정을 다시 테스트하세요.');};
['endpoint','model-name','api-key'].forEach(id=>$(id).addEventListener('input',()=>invalidateModelDraft('입력한 설정이 바뀌었습니다. 다시 테스트하세요.')));
$('test-model').onclick=()=>busy($('test-model'),async()=>{const draft=modelDraft();setFeedback('model-feedback','입력한 설정을 확인하고 있습니다…');try{const outcome=await modelGuard.test(draft,value=>api('/api/model/test',value),modelDraft);if(outcome.stale){setFeedback('model-feedback','입력이 바뀌어 이전 테스트 결과를 적용하지 않았습니다.');return;}if(!outcome.accepted)throw new Error(outcome.result?.error||'도구 호출을 확인하지 못했습니다.');setFeedback('model-feedback','현재 입력한 설정의 응답과 도구 호출을 확인했습니다.');}catch(error){setError('model-feedback',error);}finally{syncApplyState();}});
$('model-form').onsubmit=event=>{event.preventDefault();const draft=modelDraft();if(!modelGuard.canApply(draft)){setFeedback('model-feedback','먼저 현재 입력한 설정을 테스트하세요.');syncApplyState();return;}busy($('apply-model'),async()=>{try{await modelGuard.apply(draft,payload=>api('/api/model',payload));$('api-key').value='';invalidateModelLoad();setFeedback('model-feedback','테스트한 직접 API 설정을 저장했습니다. 추가 테스트는 실행하지 않았습니다.');await refresh();}catch(error){setError('model-feedback',error);}});};

function renderExecutionConnection(settings){
 const model=settings?.model||{},subscription=settings?.subscription_engines||{},box=$('active-ai'),fingerprint=JSON.stringify([model,settings?.model_ready,subscription]);if(box.dataset.state===fingerprint)return;box.dataset.state=fingerprint;box.replaceChildren();
 // One list of routes: exactly one is "현재 사용 중"; switching is always an explicit owner action.
 const selectedId=subscription.selected||'',ready=settings?.model_ready===true,directCurrent=!selectedId&&Boolean(model.model),anyCurrent=Boolean(selectedId)||directCurrent;
 const heading=element('div',undefined,'settings-section-heading');heading.append(element('h3','다음 요청이 사용할 AI'),element('p',anyCurrent?'한 번에 하나의 연결만 사용합니다. 키를 저장하거나 테스트하는 것만으로는 바뀌지 않으며, 실제 실행은 작업에서 확인합니다.':'사용할 AI 연결이 설정되지 않았습니다. 아래에서 하나를 연결하세요.'));box.append(heading);
 const switchTo=(body)=>async event=>{const button=event.currentTarget;await busy(button,async()=>{setError('active-ai-feedback','');try{await api(body.route?'/api/ai-route':'/api/subscription-engines/connect',body);await refresh();}catch(error){setError('active-ai-feedback',error);}});};
 const rows=[];
 for(const engine of subscription.engines||[]){const current=engine.id===selectedId,usable=engine.installed!==false&&engine.connected===true;let description,state,kind,action=null;
  if(current){description=engine.installed===false?'선택한 CLI를 찾지 못했습니다. 직접 API로 자동 전환하지 않습니다.':usable?'구독 CLI 우선. 웹과 Telegram 요청에 사용 중입니다.':'선택된 연결의 로그인 상태를 확인할 수 없습니다. 자동 전환하지 않습니다.';state=usable?'현재 사용 중':'확인 필요';kind=usable?'active':'attention';}
  else if(engine.installed){description='구독 CLI입니다. 공식 CLI에서 로그인을 마친 뒤 전환하세요.';state='사용 가능';kind='neutral';action=settingsAction('이 CLI 사용',switchTo({engine:engine.id,officially_authenticated:true}));}
  else{description='이 컴퓨터에서 실행 파일을 찾지 못했습니다. 공식 CLI를 설치하면 여기에 자동으로 나타납니다.';state='설치 안 됨';kind='neutral';}
  rows.push([current,settingsRow(engine.name,description,state,kind,action)]);}
 if(selectedId&&!(subscription.engines||[]).some(engine=>engine.id===selectedId))rows.push([true,settingsRow(selectedId,'선택된 연결을 이 컴퓨터에서 확인할 수 없습니다. 자동 전환하지 않습니다.','확인 필요','attention',null)]);
 if(model.model){let description,state,kind,action;
  if(directCurrent){description=`${model.model} 모델, 직접 API. ${ready?'웹과 Telegram 요청에 사용 중입니다.':'연결 확인이 필요합니다.'}`;state=ready?'현재 사용 중':'확인 필요';kind=ready?'active':'attention';action=settingsAction(ready?'설정 변경':'연결 확인',()=>focusSettingsTarget('advanced-model','test-model'));}
  else if(ready){description=`${model.model} 모델, 직접 API.`;state='사용 가능';kind='neutral';action=settingsAction('이 연결 사용',switchTo({route:'direct-api'}));}
  else{description=`${model.model} 모델, 직접 API. 저장돼 있지만 확인되지 않았습니다. 전환하려면 먼저 연결을 확인하세요.`;state='확인 필요';kind='attention';action=settingsAction('연결 확인',()=>focusSettingsTarget('advanced-model','test-model'));}
  rows.push([directCurrent,settingsRow(directRouteName(model),description,state,kind,action)]);}
 else rows.push([false,settingsRow('직접 API','OpenAI, Anthropic, OpenRouter, Ollama 같은 API 키 또는 로컬 모델','설정 안 됨','neutral',settingsAction('설정',()=>focusSettingsTarget('advanced-model')))]);
 rows.sort((a,b)=>Number(b[0])-Number(a[0]));for(const [,row] of rows)box.append(row);
 const feedback=element('p',undefined,'error');feedback.id='active-ai-feedback';feedback.setAttribute('role','status');box.append(feedback);
 const lines=selectedId?[`경로: 구독 CLI (${selectedId})`,'모델 정보 미제공','파일 작업공간 요약은 구독 CLI에서 지원하지 않습니다.']:model.model?[`경로: 직접 API (${model.provider||'제공자 미상'})`,`모델: ${model.model}`,`저장된 설정 확인: ${ready?'완료':'필요'}`]:['모델 정보 미제공'];
 box.append(settingsDisclosure('기술 세부 정보',lines));
}
// Routes are listed once in #active-ai; the former separate list stays empty.
function renderSubscriptionEngines(subscription){const box=$('subscription-engines');if(!box)return;box.hidden=true;box.replaceChildren();}
function openMobileDetail(node){if(!matchMedia('(max-width: 620px)').matches)return;node.classList.add('mobile-detail');node.querySelector('.mobile-back')?.focus({preventScroll:true});}
